// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(uint256 amount, uint256 preBalance) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(amount > 0);
        preBalance = bound(preBalance, 1, type(uint128).max);
        // Give the contract extra ether beyond the incoming msg.value.
        vm.deal(address(c), preBalance);
        vm.deal(address(this), amount);
        address recipient = address(0xBEEF);
        c.Command{value: amount}(recipient, "");
        // Rule: Command forwards exactly msg.value, so c keeps its pre-call balance.
        assertTrue(address(c).balance == preBalance, "Command must not spend pre-existing balance");
    }
}
